class Solution {
public:
    int countPalindromicSubsequence(string s) {
        vector<int> first(26, -1), last(26, -1);
        for (int i = 0; i < s.size(); i++) {
            int c = s[i] - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        int ans = 0;
        for (int c = 0; c < 26; c++) {
            if (first[c] != -1 && last[c] - first[c] > 1) {
                unordered_set<char> middle;
                for (int i = first[c] + 1; i < last[c]; i++) {
                    middle.insert(s[i]);
                }
                ans += middle.size();
            }
        }
        return ans;
    }
};

class Solution {
    public int countPalindromicSubsequence(String s) {
        int[] first = new int[26];
        int[] last = new int[26];
        java.util.Arrays.fill(first, -1);
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        int ans = 0;
        for (int c = 0; c < 26; c++) {
            if (first[c] != -1 && last[c] - first[c] > 1) {
                boolean[] seen = new boolean[26];
                int distinct = 0;
                for (int i = first[c] + 1; i < last[c]; i++) {
                    int mid = s.charAt(i) - 'a';
                    if (!seen[mid]) {
                        seen[mid] = true;
                        distinct++;
                    }
                }
                ans += distinct;
            }
        }
        return ans;
    }
}

var countPalindromicSubsequence = function(s) {
  const first = new Map();
  const last = new Map();
  for (let i = 0; i < s.length; i++) {
    if (!first.has(s[i])) first.set(s[i], i);
    last.set(s[i], i);
  }
  let ans = 0;
  for (const [ch, f] of first.entries()) {
    const l = last.get(ch);
    if (l - f > 1) {
      const distinct = new Set();
      for (let i = f + 1; i < l; i++) distinct.add(s[i]);
      ans += distinct.size;
    }
  }
  return ans;
};
